const payload = msg.payload || {};
let chatId = payload.chatId;
const messageType = payload.type;
let text = (payload.content || '').trim();

const originalMsg = msg.originalMessage || {};
let userId = originalMsg.from ? originalMsg.from.id : null;
const messageId = originalMsg.message_id;

let answerCallback = null;
if (messageType === 'callback_query') {
    text = payload.data || payload.callback_data || payload.content ||
           (originalMsg.data ? originalMsg.data : '') || '';

    if (!chatId) {
        if (originalMsg.message && originalMsg.message.chat) {
            chatId = originalMsg.message.chat.id;
        } else if (originalMsg.chat) {
            chatId = originalMsg.chat.id;
        }
    }

    if (originalMsg.from) {
        userId = originalMsg.from.id;
    }

    const callbackQueryId = payload.callback_query_id || payload.id ||
                            (originalMsg.id ? originalMsg.id.toString() : null) ||
                            (originalMsg.query_id ? originalMsg.query_id.toString() : null);

    if (callbackQueryId) {
        answerCallback = {
            payload: {
                callback_query_id: callbackQueryId,
                text: '',
                show_alert: false
            },
            topic: 'answerCallbackQuery'
        };
    }
}

if ((messageType !== 'message' && messageType !== 'callback_query') || !text || !chatId) {
    return [null, answerCallback].filter(m => m !== null);
}

if (!flow.get('victron_energy_telegram_chat_ids')) {
    flow.set('victron_energy_telegram_chat_ids', []);
}
const chatIds = flow.get('victron_energy_telegram_chat_ids');
if (!chatIds.includes(chatId)) {
    chatIds.push(chatId);
    flow.set('victron_energy_telegram_chat_ids', chatIds);
}

const command = text.split(' ')[0].toLowerCase();
const args = text.split(' ').slice(1);

if (!command.startsWith('/energy_')) {
    return [null, answerCallback].filter(m => m !== null);
}

msg.telegram = {
    chatId: chatId,
    userId: userId,
    messageId: messageId,
    command: command,
    args: args,
    originalText: text
};

if (command === '/energy_status') {
    msg.topic = 'energy_status';
} else if (command === '/energy_start') {
    msg.topic = 'energy_start';
} else if (command === '/energy_stop') {
    msg.topic = 'energy_stop';
} else if (command === '/energy_help') {
    msg.topic = 'energy_help';
} else {
    msg.topic = 'energy_unknown';
}

return [msg, answerCallback].filter(m => m !== null);

if (msg.payload && msg.payload.callback_query_id) {
    msg.payload = {
        callback_query_id: msg.payload.callback_query_id,
        text: msg.payload.text || '',
        show_alert: msg.payload.show_alert || false
    };
    msg.topic = 'answerCallbackQuery';
    return msg;
}
return null;

const fmtW = (v) => {
    if (v == null || v === '') return 'N/A';
    const n = Number(v);
    return Number.isNaN(n) ? String(v) : `${Math.round(n)} W`;
};

const energy = global.get('victron_energy_state') || {};
const disc = flow.get('victron_discretionary_load') || { enabled: false };
const auto = energy.automation || {};
const bat = energy.battery || {};
const grid = energy.grid || {};
const pv = energy.pv || {};
const load = energy.load || {};
const inv = energy.inverter || {};
const fc = energy.forecast_solar;

if (!energy.timestamp) {
    msg.payload = {
        chatId: msg.telegram.chatId,
        type: 'message',
        content: '⚠️ No Victron data yet.\n\nCheck `victron-mqtt-publisher.service` and topic `energy/victron/status`.',
        parse_mode: 'Markdown'
    };
    msg.topic = 'send';
    return msg;
}

let t = '⚡ *Victron Energy Status*\n\n';
t += `🔋 *Battery:* ${bat.soc_pct != null ? bat.soc_pct + '%' : '?'} · ${bat.voltage_v != null ? bat.voltage_v + ' V' : '?'}\n`;
t += `   Power: ${fmtW(bat.power_w)}\n\n`;
t += `🏠 *Grid L1:* ${fmtW(grid.power_l1_w)}\n`;
t += `☀️ *PV:* ${fmtW(auto.pv_power_w ?? pv.ac_output_l1_w)}\n`;
t += `📊 *Load:* ${fmtW(load.consumption_l1_w)}\n\n`;
t += '🤖 *Automation*\n';
if (auto.headroom_w != null) {
    const n = Number(auto.headroom_w);
    t += `Headroom: ${n > 0 ? '+' : ''}${Math.round(n)} W\n`;
}
t += `Can add load: ${auto.can_add_load ? '✅ Yes' : '❌ No'}\n`;
t += `Discretionary: ${disc.enabled ? '🟢 ON' : '⚫ OFF'}\n\n`;
t += `🔌 *Inverter:* ${inv.state || 'Unknown'}`;
if (inv.grid_lost) t += ' ⚠️ Grid lost';
t += '\n';

if (fc && fc.shortwave_radiation_wm2 != null) {
    t += `\n☀️ *Forecast:* ${Math.round(fc.shortwave_radiation_wm2)} W/m²`;
    if (fc.is_day === false) t += ' (night)';
}

if (energy.lastReportedMs) {
    const age = Math.max(0, Math.floor((Date.now() - energy.lastReportedMs) / 1000));
    const m = Math.floor(age / 60);
    const s = age % 60;
    t += `\n\n🕐 Updated ${m}:${String(s).padStart(2, '0')} ago`;
}

msg.payload = {
    chatId: msg.telegram.chatId,
    type: 'message',
    content: t,
    parse_mode: 'Markdown'
};
msg.topic = 'send';
return msg;

const energy = global.get('victron_energy_state') || {};
const auto = energy.automation || {};
const telegramData = msg.telegram;
const requestId = `telegram-energy-start-${Date.now()}`;

if (!auto.can_add_load) {
    const hr = auto.headroom_w != null ? Math.round(Number(auto.headroom_w)) : '?';
    return [null, null, {
        payload: {
            chatId: telegramData.chatId,
            type: 'message',
            content: `⚠️ *Cannot start discretionary load*\n\nHeadroom: ${hr} W\nNeed positive PV surplus (PV − load).`,
            parse_mode: 'Markdown'
        },
        topic: 'send'
    }];
}

const state = {
    enabled: true,
    action: 'start',
    source: 'telegram',
    updated_at: new Date().toISOString(),
    headroom_w: auto.headroom_w ?? null,
    request_id: requestId
};
flow.set('victron_discretionary_load', state);

const cmdPayload = JSON.stringify({
    action: 'start',
    source: 'telegram',
    timestamp: state.updated_at,
    enabled: true,
    request_id: requestId
});

return [
    { topic: 'energy/victron/command/discretionary/start', payload: cmdPayload },
    { topic: 'energy/victron/automation/discretionary_load/state', payload: JSON.stringify(state) },
    {
        payload: {
            chatId: telegramData.chatId,
            type: 'message',
            content: `▶️ *Discretionary load START*\n\nHeadroom: +${Math.round(Number(auto.headroom_w))} W\nRequest: \`${requestId}\``,
            parse_mode: 'Markdown'
        },
        topic: 'send'
    }
];

const telegramData = msg.telegram;
const requestId = `telegram-energy-stop-${Date.now()}`;
const energy = global.get('victron_energy_state') || {};
const auto = energy.automation || {};

const state = {
    enabled: false,
    action: 'stop',
    source: 'telegram',
    updated_at: new Date().toISOString(),
    headroom_w: auto.headroom_w ?? null,
    request_id: requestId
};
flow.set('victron_discretionary_load', state);

const cmdPayload = JSON.stringify({
    action: 'stop',
    source: 'telegram',
    timestamp: state.updated_at,
    enabled: false,
    request_id: requestId
});

return [
    { topic: 'energy/victron/command/discretionary/stop', payload: cmdPayload },
    { topic: 'energy/victron/automation/discretionary_load/state', payload: JSON.stringify(state) },
    {
        payload: {
            chatId: telegramData.chatId,
            type: 'message',
            content: `⏹ *Discretionary load STOP*\n\nRequest: \`${requestId}\``,
            parse_mode: 'Markdown'
        },
        topic: 'send'
    }
];

const helpText = `⚡ *Victron Energy Bot*\n\n` +
    `*Available Commands:*\n\n` +
    `📊 \`/energy_status\`\n` +
    `   Battery, grid, PV, load, headroom, inverter\n\n` +
    `▶️ \`/energy_start\`\n` +
    `   Start discretionary loads (when surplus PV)\n\n` +
    `⏹ \`/energy_stop\`\n` +
    `   Stop discretionary loads\n\n` +
    `❓ \`/energy_help\`\n` +
    `   Show this help\n\n` +
    `*Automation:*\n` +
    `Headroom = PV − consumption\n` +
    `Start only when headroom is positive\n\n` +
    `*Quick Actions:*`;

const inlineKeyboard = {
    inline_keyboard: [
        [
            { text: '📊 Status', callback_data: '/energy_status' },
            { text: '▶️ Start load', callback_data: '/energy_start' }
        ],
        [
            { text: '⏹ Stop load', callback_data: '/energy_stop' },
            { text: '❓ Help', callback_data: '/energy_help' }
        ]
    ]
};

msg.payload = {
    chatId: msg.telegram.chatId,
    type: 'message',
    content: helpText,
    parse_mode: 'Markdown',
    options: {
        reply_markup: JSON.stringify(inlineKeyboard)
    }
};
msg.topic = 'send';
return msg;

msg.payload = {
    chatId: msg.telegram.chatId,
    type: 'message',
    content: `❓ Unknown energy command: ${msg.telegram.originalText}\n\nType /energy_help for available commands.`
};
msg.topic = 'send';
return msg;
